def transform(grid):
    h = len(grid)
    w = len(grid[0])

    # Find horizontal separator row (all 9s)
    sep_row = None
    for r in range(h):
        if all(grid[r][c] == 9 for c in range(w)):
            sep_row = r
            break

    if sep_row is None:
        return [[0] * w]

    # Output is top section size (rows 0 to sep_row-1)
    output = [[0] * w for _ in range(sep_row)]

    for r in range(sep_row):
        for c in range(w):
            top_val = grid[r][c]
            bot_val = grid[sep_row + 1 + r][c]
            # Output 2 where both sections match (both 0 or both background colors)
            if top_val == bot_val:
                output[r][c] = 2

    return output
